    uint16_t wNameSeed;
    int32_t nScratch;
    uint32_t nComponentData;
    D2UnitStrc* pOwner;
    uint32_t nStatIndex;
    D2StatListExStrc* pStatListEx;
    D2DataTableTxtStrc* pDataTable;
    D2ItemStatCostTxt* pStatCostTxt;
    uint32_t nComponentIdx;
    int nIndex;
    int32_t nSizeInBits;
    D2StatStrc aStatBuf[16];
    int nStatValue;
    char* pComponentBytes;
    int32_t nStatCount;
    D2BitBufferStrc bitBuffer;
    int bHasStats;
    uint8_t aPacket[260];
    uint8_t byComponent;
    eD2UnitType eUnitType;
    BOOL BVar1;
    eD2PlayerAnimMode eAnimMode;
    D2ClientStrc* pClientSaved = pClient;
