// This is just a thin shim around NET_D2GS_SERVER_SendPacket_Helper.
void __fastcall NET_D2GS_SERVER_Send_0xAA_AddUnit_0xA8_SetState(D2ClientStrc * pClient, uint8_t * pPacket, size_t nPacketSize) {
    SCMD_QueuePacketForClient(pPacket, nPacketSize, pClient);
}

void __fastcall NET_D2GS_SERVER_Send_0x59_AssignPlayer(D2ClientStrc * pClient, uint32_t nUnitGUID, uint8_t byCharClass2, char * szCharNameSrc, uint16_t wSrcPosX, uint16_t wSrcPosY) {
    uint8_t byPacketId[26];
    memset(byPacketId + 22, 0, 4 * sizeof(byPacketId[0]));
    byPacketId[5] = byCharClass2;
    d2_store24((char*)&byPacketId + 1, (uint32_t)nUnitGUID & 0xffffffu);
    byPacketId[0] = 'Y';
    byPacketId[4] = (uint8_t)(nUnitGUID >> 0x18);
    memset(byPacketId + 6, 0, 16 * sizeof(byPacketId[0]));
    Storm::Source::SSTR::SStrCopy((char*)(byPacketId + 6), szCharNameSrc, 0x7fffffff);
    *(uint16_t*)((char*)&byPacketId + 22) = wSrcPosX;
    *(uint16_t*)((char*)&byPacketId + 24) = wSrcPosY;
    SCMD_QueuePacketForClient(byPacketId, 0x1a, pClient);
    D2UnitStrc* pUnit = Clients::CLIENTS_GetControlUnit(pClient, 0);
    ::SGAMEDATA* pGame = Clients::CLIENT_GetGame(pClient);
    D2UnitStrc* pTargetUnit = UNIT::SUnit::FindUnitFromTable(pGame, UNIT_PLAYER, nUnitGUID);
    if (pTargetUnit) {
      NET_D2GS_SERVER_Send_0x75_UPDATEROSTER(pUnit, pTargetUnit);
    }

    Fog::Debug::GuardStack();
}

// Server-to-client gold pickup notification. Opcode 0x19 encodes delta < 255 (2 bytes).
// For larger values, reuses SetAttribute opcodes (0x1D/0x1E/0x1F) with stat ID 0x0E (gold).
// Called when player picks up gold pile or receives gold from trade/vendor.
void __fastcall NET_D2GS_SERVER_Send_0x19_STATCHANGE_CONTROL_GOLD_BYTE_DELTA(D2ClientStrc * pClient, uint32_t nNewValue, uint32_t nCurrentValue) {
    uint8_t aPacket[6];
    int nGoldDelta = nNewValue - nCurrentValue;
    if (nGoldDelta - 1U < 0xfe) {
      *(uint16_t*)(char*)&nCurrentValue = (uint16_t)((uint16_t)(uint8_t)(char)nGoldDelta << 8 | (uint16_t)(uint8_t)0x19);
      SCMD_QueuePacketForClient((uint8_t*)&nCurrentValue, 2, pClient);
      return;
    }
    if (nNewValue < 0xff) {
      d2_store24((char*)&nCurrentValue, (uint32_t)((uint32_t)((uint32_t)(uint8_t)(char)nNewValue << 16 | (uint32_t)(uint16_t)0xe1d) & 0xffffffu));
      SCMD_QueuePacketForClient((uint8_t*)&nCurrentValue, 3, pClient);
      return;
    }
    if (nNewValue < 0xffff) {
      nCurrentValue = (uint32_t)((uint32_t)(uint16_t)(short int)nNewValue << 16 | (uint32_t)(uint16_t)0xe1e);
      SCMD_QueuePacketForClient((uint8_t*)&nCurrentValue, 4, pClient);
      return;
    }

    aPacket[0] = 0x1f;
    aPacket[1] = 0xe;
    *(uint32_t*)((char*)&aPacket + 2) = nNewValue;
    SCMD_QueuePacketForClient(aPacket, 6, pClient);
}

// @wasnamed Send0x9DItemInSocket - one name on two different functions.
// @evidence Loops INVENTORY_GetFirstItem/GetNextItem plus GetCarriedItem, sets
// server flag 8 and sends one 0x9D per item. 0053d330 sends exactly one.
void __fastcall Send0x9DAllSocketedItems(D2ClientStrc * pClient, D2UnitStrc * pUnit, uint32_t eItemFlags) {
    bool _bHasInv;
    bool bHasInv;
    bool bIsRemoved;
    D2UnitStrc* pSocketItem;
    _bHasInv = D2Common::ITEMS::Items::ITEM_GetItemsTxt_bHasInv(pUnit);
    if (!_bHasInv) {
      return;
    }

    uint32_t nRemovedFlag = D2Common::ITEMS::Items::ITEMFLAG_CheckFlag(eItemFlags, ITEMFLAG_REMOVED);
    if (!(!nRemovedFlag && pUnit->pInventory)) {
      return;
    }

    for (pSocketItem = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(pUnit->pInventory); pSocketItem; pSocketItem = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pSocketItem)) {
      D2UnitStrc* pSocketedItem;
      pSocketedItem = D2Common::INVENTORY::Inventory::GetCarriedItem(pSocketItem);
      D2Common::ITEMS::Items::ITEM_SetServerSideFlag(&eItemFlags, 8, 1);
      NET_D2GS_SERVER_Send_0x9D_ITEMUNITEX(pClient, pUnit, pSocketedItem, 0x13, eItemFlags, 0);
    }
}

// Sends opcode 0x9C item-world packet to pClient. Fills D2GSPacketSrv0x9C with action, item GUID, container slot (relative to the client's player unit), then serialises the item into the bitstream with eItemFlag temporarily applied. Sends socketed children via Send0x9DItemInSocket. Halts if player unit is null or serialised size >= 0xFD.
void __fastcall NET_D2GS_SERVER_Send_0x9C_ITEMEX(D2ClientStrc * pClient, D2UnitStrc * pUnit, int nItemAction, eD2ItemFlag eItemFlag, uint32_t nParam) {
    D2GSPacketSrv0x9C sPacket;
    int32_t nLine;
    D2UnitStrc* pPlayerUnit_lcl = Clients::CLIENTS_GetControlUnit(pClient, 0);
    if (!pPlayerUnit_lcl) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x77b);
      exit(-1);
    } else {
      eD2ItemFlag eSavedItemFlags;
      sPacket.nPacketId = 0x9c;
      sPacket.nAction = (uint8_t)nItemAction;
      if (!pUnit) {
        sPacket.nItemGUID = -1;
      } else {
        sPacket.nItemGUID = pUnit->nUnitGUID;
      }

      sPacket.nCategory = D2Common::Units::GetItemComponent(pPlayerUnit_lcl, pUnit);
      eSavedItemFlags = D2Common::ITEMS::Items::ITEM_GetItemData_eD2ItemFlag(pUnit);
      D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pUnit, eItemFlag, 1);
      memset(sPacket.aBitStream, 0, 0xf4);
      nLine = D2Common::ITEMS::Items::SerializeItem(pUnit, (uint8_t*)sPacket.aBitStream, 0xf4, nullptr, 0, nParam);
      if (nLine + 8U < 0xfd) {
        sPacket.nFullPacketSize = (uint8_t)(nLine + 8U);
        D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pUnit, ITEMFLAG_TAGGED | ITEMFLAG_DROW | ITEMFLAG_CURSED | ITEMFLAG_STAFFMODS | ITEMFLAG_MAGICAL | ITEMFLAG_RUNEWORD | ITEMFLAG_CRUDE | ITEMFLAG_PLAYERNAME | ITEMFLAG_SAVED | ITEMFLAG_ETHEREAL | ITEMFLAG_COMPACT | ITEMFLAG_100000 | ITEMFLAG_SERVER | ITEMFLAG_RESTRICT | ITEMFLAG_BEGINNER | ITEMFLAG_BODYPART | ITEMFLAG_HARDCORE | ITEMFLAG_DISABLED | ITEMFLAG_NEW | ITEMFLAG_MONSTER | ITEMFLAG_SOCKETED | ITEMFLAG_SORTED | ITEMFLAG_RESTORED | ITEMFLAG_BROKEN | ITEMFLAG_TAKEN | ITEMFLAG_ADDED | ITEMFLAG_REMOVED | ITEMFLAG_IDENTIFIED | ITEMFLAG_IGNORE | ITEMFLAG_CURSOR | ITEMFLAG_BOUGHT | ITEMFLAG_RELOAD, 0);
        D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pUnit, eSavedItemFlags, 1);
        SCMD_QueuePacketForClient(&sPacket.nPacketId, (uint32_t)sPacket.nFullPacketSize, pClient);
        Send0x9DAllSocketedItems(pClient, pUnit, eItemFlag);
        Fog::Debug::GuardStack();
        return;
      }

      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x78c);
      exit(-1);
    }
}

